#!/usr/bin/env python3
"""Writes synthetic.json: an analytic polar table and expected lookups (TASK-019).

CL(alpha, Re, Ma) = gL(alpha) * (1 + 0.05 ln(Re/1e5)) * (1 + 0.2 Ma)
CD(alpha, Re, Ma) = gD(alpha) * (1 + 0.1 ln(1e5/Re)) * (1 + 0.5 Ma)

gL and gD are piecewise linear in alpha with kinks only at table nodes, and
the Re/Mach factors are linear in ln(Re) and Ma, so trilinear interpolation in
(Ma, ln Re, alpha) reproduces the functions exactly. Expected values below are
evaluated from these closed forms (at the clamped point when a query lies
outside the table), independently of the Rust implementation. Synthetic data,
not a measured airfoil. Run from the repository root.
"""
import json
import math
from pathlib import Path

PI = math.pi
ALPHA = [-PI, -2.5, -PI / 2, -0.3, 0.0, 0.3, PI / 2, 2.5, PI]
GL = [0.0, 0.7, 0.0, -0.6 * PI, 0.0, 0.6 * PI, 0.0, -0.7, 0.0]  # flat-plate-like reverse-flow lift
GD = [0.05, 1.0, 1.9, 0.03, 0.01, 0.03, 1.9, 1.0, 0.05]
RE = [2.0e4, 1.0e5, 5.0e5]
MACH = [0.0, 0.3, 0.6]


def piecewise(nodes, values, x):
    for i in range(len(nodes) - 1):
        if nodes[i] <= x <= nodes[i + 1]:
            t = (x - nodes[i]) / (nodes[i + 1] - nodes[i])
            return values[i] + t * (values[i + 1] - values[i])
    raise ValueError(x)


def clamp(x, lo, hi):
    return min(max(x, lo), hi)


def exact(alpha, re, mach):
    a, r, m = clamp(alpha, ALPHA[0], ALPHA[-1]), clamp(re, RE[0], RE[-1]), clamp(mach, MACH[0], MACH[-1])
    outside = (a, r, m) != (alpha, re, mach)
    cl = piecewise(ALPHA, GL, a) * (1 + 0.05 * math.log(r / 1e5)) * (1 + 0.2 * m)
    cd = piecewise(ALPHA, GD, a) * (1 + 0.1 * math.log(1e5 / r)) * (1 + 0.5 * m)
    return cl, cd, outside


cl_table, cd_table = [], []
for m in MACH:  # flattened index = (iMach*nRe + iRe)*nAlpha + iAlpha
    for r in RE:
        for a in ALPHA:
            cl, cd, _ = exact(a, r, m)
            cl_table.append(cl)
            cd_table.append(cd)

QUERIES = [
    ("node", 0.3, 1.0e5, 0.3), ("interior", 0.1, 3.0e4, 0.15), ("negative stall", -1.0, 2.5e5, 0.05),
    ("reverse flow", 2.8, 2.0e5, 0.45), ("reverse flow negative", -3.0, 6.0e4, 0.5),
    ("alpha -pi", -PI, 1.0e5, 0.0), ("alpha +pi", PI, 5.0e5, 0.6), ("zero alpha", 0.0, 7.0e4, 0.2),
    ("Re below table", 0.2, 1.0e3, 0.1), ("Re above table", -0.2, 1.0e7, 0.1),
    ("Mach above table", 1.2, 1.5e5, 0.9), ("alpha beyond table", 3.5, 1.0e5, 0.3),
    ("all outside", -4.0, 1.0e8, 2.0),
]
queries = []
for name, a, r, m in QUERIES:
    cl, cd, outside = exact(a, r, m)
    queries.append({"name": name, "alphaRad": a, "reynolds": r, "mach": m, "cl": cl, "cd": cd, "outsideValidity": outside})

fixture = {
    "description": "Analytic synthetic polar (TASK-019); generated by tests/fixtures/polars/generate.py; not a measured airfoil",
    "alphaRad": ALPHA, "reynolds": RE, "mach": MACH, "cl": cl_table, "cd": cd_table,
    "tolerance": {"absolute": 1e-12},
    "queries": queries,
}
out = Path(__file__).with_name("synthetic.json")
out.write_text(json.dumps(fixture, indent=2) + "\n")
print(f"wrote {out}: {len(cl_table)} table values, {len(queries)} queries")
